import React, { useState, useEffect } from "react";
import axios from "axios";
import { Link } from "react-router-dom";
import { FiSearch, FiShoppingBag, FiCalendar, FiChevronLeft, FiChevronRight } from "react-icons/fi";

const AdminSellersOrdersListLayer = () => {
  const now = new Date();
  const currentMonthStr = String(now.getMonth() + 1);
  const currentYearNum = now.getFullYear();
  const currentYearStr = String(currentYearNum);

  const [sellers, setSellers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [month, setMonth] = useState(currentMonthStr);
  const [year, setYear] = useState(currentYearStr);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalSellers, setTotalSellers] = useState(0);
  const limit = 10;

  const months = [
    { value: "1", label: "January" },
    { value: "2", label: "February" },
    { value: "3", label: "March" },
    { value: "4", label: "April" },
    { value: "5", label: "May" },
    { value: "6", label: "June" },
    { value: "7", label: "July" },
    { value: "8", label: "August" },
    { value: "9", label: "September" },
    { value: "10", label: "October" },
    { value: "11", label: "November" },
    { value: "12", label: "December" },
  ];

  // Provide 5 past years + current year + 10 future years
  const years = Array.from({ length: 16 }, (_, i) => String(currentYearNum - 5 + i));

  const fetchSellers = async (page = 1, searchQuery = "", monthVal = month, yearVal = year) => {
    try {
      setLoading(true);
      const baseURL = process.env.REACT_APP_BACKEND_URL || "";
      let url = `${baseURL}/api/productRequest/admin/sellers-summary?page=${page}&limit=${limit}&search=${encodeURIComponent(searchQuery)}`;
      if (monthVal) url += `&month=${monthVal}`;
      if (yearVal) url += `&year=${yearVal}`;

      const res = await axios.get(url);

      if (res.data.success) {
        setSellers(res.data.sellers || []);
        setCurrentPage(res.data.currentPage || 1);
        setTotalPages(res.data.totalPages || 1);
        setTotalSellers(res.data.totalSellers || 0);
      }
    } catch (err) {
      console.error("Error fetching sellers order summary:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSellers(currentPage, search, month, year);
  }, [currentPage, search, month, year]);

  const handleSearchChange = (e) => {
    setSearch(e.target.value);
    setCurrentPage(1);
  };

  const handleMonthChange = (e) => {
    setMonth(e.target.value);
    setCurrentPage(1);
  };

  const handleYearChange = (e) => {
    setYear(e.target.value);
    setCurrentPage(1);
  };

  return (
    <div className="card border-0 shadow-sm" style={{ borderRadius: "12px" }}>
      {/* Header with Title & Month/Year/Search Filters */}
      <div className="card-header bg-white py-3 border-bottom-0 d-flex flex-wrap justify-content-between align-items-center gap-3">
        <h5 style={{ fontWeight: "700", color: "#0F172A", margin: 0, fontSize: "18px" }}>
          Registered Sellers Orders Summary
        </h5>

        <div className="d-flex align-items-center gap-2 flex-wrap">
      
          <div
            className="d-flex align-items-center gap-2 bg-light px-3 rounded-3 border"
            style={{ height: "42px" }}
          >
            <FiCalendar style={{ color: "#64748B", fontSize: "16px" }} />
            <select
              value={month}
              onChange={handleMonthChange}
              style={{
                border: "none",
                outline: "none",
                fontSize: "14px",
                fontWeight: "600",
                color: "#1E293B",
                backgroundColor: "transparent",
                cursor: "pointer",
                height: "100%",
              }}
            >
              <option value="">All Months</option>
              {months.map((m) => (
                <option key={m.value} value={m.value}>
                  {m.label}
                </option>
              ))}
            </select>
          </div>

        
          <div
            className="d-flex align-items-center gap-2 bg-light px-3 rounded-3 border"
            style={{ height: "42px" }}
          >
            <select
              value={year}
              onChange={handleYearChange}
              style={{
                border: "none",
                outline: "none",
                fontSize: "14px",
                fontWeight: "600",
                color: "#1E293B",
                backgroundColor: "transparent",
                cursor: "pointer",
                height: "100%",
              }}
            >
              <option value="">All Years</option>
              {years.map((y) => (
                <option key={y} value={y}>
                  {y}
                </option>
              ))}
            </select>
          </div>

     
          <div
            className="d-flex align-items-center gap-2 bg-light px-3 rounded-3 border"
            style={{ height: "42px", minWidth: "340px" }}
          >
            <FiSearch style={{ color: "#64748B", fontSize: "16px", flexShrink: 0 }} />
            <input
              type="text"
              placeholder="Search seller by name, contact person, or mobile"
              value={search}
              onChange={handleSearchChange}
              style={{
                border: "none",
                outline: "none",
                backgroundColor: "transparent",
                fontSize: "14px",
                color: "#1E293B",
                width: "340px",
                height: "100%",
              }}
            />
          </div>
        </div>
      </div>

  
      <div className="card-body p-0">
        {loading ? (
          <div className="text-center py-5">
            <div className="spinner-border text-primary" role="status">
              <span className="visually-hidden">Loading...</span>
            </div>
            <p className="mt-2 text-muted fw-semibold" style={{ fontSize: "14px" }}>Loading sellers...</p>
          </div>
        ) : sellers.length === 0 ? (
          <div className="text-center py-5">
            <FiShoppingBag size={40} style={{ color: "#94A3B8", marginBottom: "12px" }} />
            <h6 style={{ fontWeight: "700", color: "#334155" }}>No Registered Sellers Found</h6>
          </div>
        ) : (
          <div className="table-responsive">
            <table className="table table-hover align-middle mb-0">
              <thead style={{ backgroundColor: "#F8FAFC", borderBottom: "2px solid #E2E8F0" }}>
                <tr>
                  <th style={{ padding: "14px 20px", color: "#475569", fontWeight: "700", fontSize: "13.5px" }}>Serial No.</th>
                  <th style={{ padding: "14px 20px", color: "#475569", fontWeight: "700", fontSize: "13.5px" }}>Seller Name</th>
                  <th style={{ padding: "14px 20px", color: "#475569", fontWeight: "700", fontSize: "13.5px" }}>Contact Details</th>
                  <th style={{ padding: "14px 20px", color: "#475569", fontWeight: "700", fontSize: "13.5px" }}>Completed Orders</th>
                  {/* <th style={{ padding: "14px 20px", color: "#475569", fontWeight: "700", fontSize: "13.5px" }}>Total Amount</th> */}
                  <th style={{ padding: "14px 20px", color: "#475569", fontWeight: "700", fontSize: "13.5px" }}>Platform Fee</th>
                </tr>
              </thead>
              <tbody>
                {sellers.map((seller, index) => {
                  const serialNo = (currentPage - 1) * limit + index + 1;
                  return (
                    <tr key={seller._id}>
                      <td style={{ padding: "14px 20px", fontWeight: "600", color: "#64748B", fontSize: "14px" }}>
                        {serialNo}
                      </td>
                      <td style={{ padding: "14px 20px" }}>
                        <Link
                          to={`/adminOrders/${seller._id}${month || year ? `?month=${month}&year=${year}` : ""}`}
                          style={{
                            fontWeight: "700",
                            color: "#A847F0",
                            fontSize: "14.5px",
                            textDecoration: "underline"
                          }}
                        >
                          {seller.shopName}
                        </Link>
                        
                      </td>
                      <td style={{ padding: "14px 20px" }}>
                        {seller.contactPerson && seller.contactPerson !== "N/A" && (
                          <div style={{ fontSize: "12px", color: "#64748B" }}>
                             {seller.contactPerson} <br/>
                             ({seller.mobile})
                          </div>
                        )}
                        
                      </td>
                      <td style={{ padding: "14px 20px" }}>
                        <span
                          className="badge px-3 py-2"
                          style={{
                            backgroundColor: seller.totalOrders > 0 ? "#F3E8FF" : "#F1F5F9",
                            color: seller.totalOrders > 0 ? "#7E22CE" : "#64748B",
                            border: `1px solid ${seller.totalOrders > 0 ? "#E9D5FF" : "#E2E8F0"}`,
                            borderRadius: "6px",
                            fontSize: "13px",
                            fontWeight: "700"
                          }}
                        >
                          {seller.totalOrders}
                        </span>
                      </td>
                      {/* <td style={{ padding: "14px 20px", fontWeight: "700", color: "#0F172A", fontSize: "14px" }}>
                        Rs. {Number(seller.totalAmount || 0).toFixed(2)}
                      </td> */}
                      <td style={{ padding: "14px 20px", fontWeight: "700", color: "#059669", fontSize: "14px" }}>
                        Rs. {Number(seller.totalPlatformFee || 0).toFixed(2)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
        <div className="card-footer bg-white py-3 border-top d-flex justify-content-between align-items-center flex-wrap gap-2">
          <span style={{ fontSize: "13.5px", color: "#64748B", fontWeight: "500" }}>
            Showing page <strong>{currentPage}</strong> of <strong>{totalPages}</strong> ({totalSellers} sellers)
          </span>

          <div className="d-flex align-items-center gap-1">
            <button
              disabled={currentPage <= 1}
              onClick={() => setCurrentPage((prev) => Math.max(1, prev - 1))}
              className="btn btn-sm btn-outline-secondary d-flex align-items-center gap-1"
              style={{ fontWeight: "600", borderRadius: "6px" }}
            >
              <FiChevronLeft /> Prev
            </button>
            <button
              disabled={currentPage >= totalPages}
              onClick={() => setCurrentPage((prev) => Math.min(totalPages, prev + 1))}
              className="btn btn-sm btn-outline-secondary d-flex align-items-center gap-1"
              style={{ fontWeight: "600", borderRadius: "6px" }}
            >
              Next <FiChevronRight />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminSellersOrdersListLayer;
